INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (13, 14, 'theory', 'Quiz: inheritance and composition');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 14, 0, 'class Dog(Animal): ... What does isinstance(Dog(), Animal) return?', '["False", "True", "An error", "None"]', 1, 'Dog is a subclass of Animal, so a dog is an animal.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 14, 1, 'Why does a subclass''s __init__ call super().__init__(...)?', '["To delete the parent", "So the parent constructor creates the shared attributes", "To make object creation faster", "It is an optional style choice"]', 1, 'Without this call the parent''s shared attributes do not appear, and the object is left half-built.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 14, 2, 'A car keeps an Engine object inside as an attribute. What is this relationship called?', '["Inheritance", "Composition", "Polymorphism", "Encapsulation"]', 1, 'Composition expresses "has a": a car has an engine but is not one.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 14, 3, 'What happens when you create an instance of an abstract class with an unimplemented @abstractmethod?', '["The object is created", "TypeError", "An empty method is called", "NameError"]', 1, 'An abstract class is a template: until all abstract methods are implemented, you cannot create an instance.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 14, 4, 'd = Dog(); the class Dog inherits Animal. What is type(d) is Animal?', '["True", "False", "An error", "None"]', 1, 'type returns the exact class, which is Dog; isinstance, not type, takes the hierarchy into account.');
